      }
      if (input.diffTree) {
        s.diffTree = writeDiffTree(input.diffTree, s.diffTree?.hunks ?? captured!, s.diffTree);
        s.status = 'draft';
      }
      if (input.title) s.title = input.title;
      if (input.changes) {
        if (input.changes.length !== s.changes.length || new Set(input.changes.map(c => c.id)).size !== s.changes.length) throw new Error('Annotate every generated change exactly once');
        for (const change of input.changes) {
          const previous = s.changes.find(c => c.id === change.id);
          if (!previous || previous.documentId !== change.documentId || previous.nodeId !== change.nodeId
            || !((previous.type === 1 || previous.type === 4) ? [1,4].includes(change.type) : previous.type === change.type)) throw new Error('Invalid change target or type');
        }
        s.changes = input.changes;
      }
      if (input.migrations) {
        const issues = migrationIssues(s.documents, input.migrations);
        if (issues.length) throw Error(issues.map(i => `${i.migrationId} ${i.role}: ${i.message}`).join('; '));
        s.migrations = input.migrations;
        s.status = 'draft';
      }
      if (input.status === 'ready') this.validateReady(s);
      if (input.status) s.status = input.status;
      return { ...summarizeChangeSession(s), version: s.version + 1 };
    });
  }
  private validateReady(s: DiagramChangeSession) {
    if (s.diffTree) validateDiffTree(s.diffTree);
    if (s.repositoryId && s.documents.some(doc => doc.repositoryId !== s.repositoryId)) throw Error('ChangeSession contains a canvas owned by another repository');
    const issues = migrationIssues(s.documents, s.migrations ?? []);
    if (issues.length) throw Error(issues.map(i => `${i.migrationId} ${i.role}: ${i.message}`).join('; '));
    if (!s.changes.length) throw new Error('Session has no changes');
    const visited = new Set<string>(), visiting = new Set<string>();
    const visit = (id: string) => {
      if (visiting.has(id)) throw new Error('Cyclic change dependency');
      if (visited.has(id)) return;
      const change = s.changes.find(c => c.id === id); if (!change) throw new Error('Unknown change dependency');
      visiting.add(id); change.dependsOn.forEach(visit); visiting.delete(id); visited.add(id);
    };
    s.changes.forEach(c => visit(c.id));
    for (const doc of s.documents) for (const edge of doc.proposed.document.edges) {
      validateConnectionAnchor(doc.proposed.document.scene, edge.source); validateConnectionAnchor(doc.proposed.document.scene, edge.target);
    }
    for (const change of s.changes.filter(c => c.type === 2)) {
      const doc = this.document(s, change.documentId);
      const connected = doc.proposed.document.edges.some(edge => edge.target.displayNodeId === change.nodeId
        // The owner may be introduced/replaced by this proposal. Require its
        // containing diagram to exist in the baseline, not the owner node itself.
        && !!doc.baseline && !!connectionBox(doc.baseline.document.scene, edge.source.displayNodeId));
      if (!connected) throw new Error(`Added diagram needs an edge from an existing diagram: ${change.title}`);
    }
  }
}
"},{"path":"application/mapping/changes/diffSessionWorkflowService.ts","text":"import type { DiffSessionRun } from '../../../domain/mapping/changes/diffSessionWorkflow';
import { createHash } from 'node:crypto';
import { z } from 'zod';
import { requireAiEnabled } from '../../core/errors';
import { runAgentWorkflow } from '../../core/agents/agentWorkflow';
import type { AgentDiagrammingSessionService } from '../agent/sessionService';
import type { ChangeSessionCapture, ChangeSessionService } from './changeSessionService';
import { DiffSessionTools, type DiffSessionSourceReader } from './diffSessionTools';
import { createDiffSessionWorkflow, DIFF_SESSION_MODEL, type DiffSessionAgentSession, type DiffSessionMetric, type DiffSessionPrompts, type DiffSessionRuntime } from './diffSessionWorkflow';

export const diffSessionRequestSchema = z.object({
  requestId: z.string().min(1).max(200), title: z.string().trim().min(1).max(200),
  baselineChangeSessionId: z.string().min(1).max(200).optional(), repositoryId: z.string().min(1).max(200).optional(),
  commits: z.array(z.string().min(1).max(200)).max(2000).optional(),
  comparisonBase: z.string().regex(/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/).nullable().optional(), head: z.string().min(1).max(200).optional(),
  canvasId: z.string().min(1).max(200).optional()
}).strict().refine(input => input.baselineChangeSessionId ? !input.repositoryId && !input.commits && !input.head && !input.canvasId && input.comparisonBase === undefined
  : !!input.repositoryId && (!!input.commits?.length || input.comparisonBase !== undefined && !!input.head && !!input.commits), 'Specify a baseline ChangeSession OR a repository and commits');
export type DiffSessionRequest = z.infer<typeof diffSessionRequestSchema>;
export type { DiffSessionRun } from '../../../domain/mapping/changes/diffSessionWorkflow';
export interface DiffSessionRunStore {
  create(run: DiffSessionRun): Promise<boolean>;
  read(id: string): Promise<DiffSessionRun | undefined>;
  save(run: DiffSessionRun): Promise<void>;
  artifact(id: string, name: string, data: unknown): Promise<void>;
}

export class DiffSessionWorkflowService {
  private active = new Map<string, AbortController>();
  private live = new Map<string, DiffSessionRun>();
  private starts = new Map<string, Promise<DiffSessionRun>>();
  constructor(private readonly changes: ChangeSessionService, private readonly agent: AgentDiagrammingSessionService,
    private readonly runtime: DiffSessionRuntime, private readonly store: DiffSessionRunStore,
    private readonly options: { enabled: boolean; sourceRoot: string; loadPrompts(): Promise<DiffSessionPrompts>;
      sourceReader(capture: ChangeSessionCapture): Promise<DiffSessionSourceReader> }) {}

  async start(raw: unknown): Promise<DiffSessionRun> {
    requireAiEnabled(this.options.enabled);
    const request = diffSessionRequestSchema.parse(raw);
    const id = `diff-run-${createHash('sha256').update(request.requestId).digest('hex').slice(0, 32)}`;
    const pending = this.starts.get(id);
    if (pending) {
      const run = await pending;
      if (JSON.stringify(run.request) !== JSON.stringify(request)) throw Error('REQUEST_ID_CONFLICT');
      return run;
    }
    const start = this.begin(id, request); this.starts.set(id, start);
    try { return await start; } finally { this.starts.delete(id); }
  }
  private async begin(id: string, request: DiffSessionRequest) {
    const now = new Date().toISOString();
    const run: DiffSessionRun = { id, request, workflowId: 'diff-session-create', status: 'running', stage: 'capture',
      model: DIFF_SESSION_MODEL, createdAt: now, updatedAt: now };
    if (!await this.store.create(run)) {
      const existing = await this.get(id);
      if (!existing || JSON.stringify(existing.request) !== JSON.stringify(request)) throw Error('REQUEST_ID_CONFLICT');
      return existing;
    }
    const abort = new AbortController(); this.active.set(id, abort); this.live.set(id, run);
    void this.execute(run, abort.signal).catch(() => {}).finally(() => { this.active.delete(id); this.live.delete(id); });
    return structuredClone(run);
  }
  private async execute(run: DiffSessionRun, signal: AbortSignal) {
    let session: DiffSessionAgentSession | undefined;
    const metrics: DiffSessionMetric[] = [];
    const save = () => { run.updatedAt = new Date().toISOString(); return this.store.save(run); };
    try {
      const capture = await this.changes.capture(run.request);
      if (!capture.context || !capture.hunks.length) throw Error('The workflow requires pinned commits with captured hunks');
      signal.throwIfAborted();
      await this.store.artifact(run.id, 'context', capture);
      const prompts = await this.options.loadPrompts();
      await this.store.artifact(run.id, 'prompts', prompts);
      const tools = new DiffSessionTools(capture, this.changes, this.agent, await this.options.sourceReader(capture),
        run.id, run.request.title, async id => { run.changeSessionId = id; await save(); });
      session = await this.runtime.openSession({ sourceRoot: this.options.sourceRoot, signal, tools: step => tools.tools(step),
        onProgress: message => { run.message = message; }, onMetric: metric => { metrics.push(metric); } });
      run.agentSessionId = session.sessionId; await save();
      const result = await runAgentWorkflow(createDiffSessionWorkflow(prompts, capture), async request => {
        run.stage = request.stepId as 'analyze' | 'materialize'; run.message = `Running ${request.stepId}`;
        await this.store.artifact(run.id, `${request.stepId}-request`, { role: 'user', content: request.prompt }); await save();
        const output = await session!.runStep(request);
        await this.store.artifact(run.id, `${request.stepId}-response`, output);
        await this.store.artifact(run.id, 'conversation', session!.transcript());
        await this.store.artifact(run.id, 'performance', metrics);
        return output;
      }, { signal });
      run.stage = 'validate'; await save();
      const proposal = await this.changes.get(result.changeSessionId!);
      if (proposal.id !== tools.changeSessionId || proposal.status !== 'ready') throw Error('Workflow did not produce its own ready proposal');
      run.changeSessionId = proposal.id; run.status = 'completed'; run.message = 'ChangeSession ready for review';
    } catch (error) {
      run.status = signal.aborted ? 'cancelled' : 'failed';
      run.error = error instanceof Error ? error.message : String(error);
    } finally {
      try {
        if (session) await this.store.artifact(run.id, 'conversation', session.transcript());
        await this.store.artifact(run.id, 'performance', metrics);
      } finally { session?.dispose(); await save(); }
    }
  }
  async get(id: string) {
    const run = this.live.has(id) ? structuredClone(this.live.get(id)!) : await this.store.read(id);
    if (run?.status === 'running' && !this.active.has(id) && !this.starts.has(id)) run.status = 'interrupted';
    return run;
  }
  async cancel(id: string) { this.active.get(id)?.abort(new Error('Workflow cancelled')); return this.get(id); }
  dispose() { for (const abort of this.active.values()) abort.abort(new Error('Server shutting down')); this.runtime.dispose(); }
}
"},{"path":"application/mapping/changes/diffSessionTools.ts","text":"import { compactDiffSessionToolResult } from './diffSessionToolResults';
import { z } from 'zod';
import { canvasDisplayNodes } from '../../../domain/mapping/workspace/canvasDisplayNode';
import { agentToolSchemas, canvasApiSpec, type AgentToolName } from '../../../domain/mapping/agent/contracts';
import { diffTreeInputSchema } from '../../../domain/mapping/changes/diffTree';
import { CanvasApiProjection } from '../agent/apiProjection';
import type { AgentDiagrammingSessionService } from '../agent/sessionService';
import type { ChangeSessionCapture, ChangeSessionService } from './changeSessionService';
import type { DiffSessionStep, DiffSessionTool } from './diffSessionWorkflow';

const sourceSchema = z.object({ path: z.string().min(1), revision: z.string().optional(), startLine: z.number().int().positive().default(1), limit: z.number().int().min(1).max(400).default(200) }).strict();
export interface DiffSessionSourceReader { (input: z.infer<typeof sourceSchema>): Promise<unknown> }

/** Stage and target restrictions are enforced here, independently of model instructions. */
export class DiffSessionTools {
  private readonly projection = new CanvasApiProjection();
  changeSessionId?: string;
  constructor(private readonly capture: ChangeSessionCapture, private readonly changes: ChangeSessionService,
    private readonly agent: AgentDiagrammingSessionService, private readonly readSource: DiffSessionSourceReader,
    private readonly requestId: string, private readonly title: string,
    private readonly onCreated: (id: string) => Promise<void>) {}

  private tool(name: string, description: string, schema: z.ZodType, execute: (input: any) => Promise<unknown>): DiffSessionTool {
    return { name, description, schema: z.toJSONSchema(schema), execute: async raw => compactDiffSessionToolResult(name, await execute(schema.parse(raw))) };
  }
  private frozenSearch(input: z.infer<typeof agentToolSchemas['diagram-search']>) {
    const documents = this.capture.documents.filter(doc => !input.representationId || input.representationId === doc.id);
    const nodes = documents.flatMap(doc => canvasDisplayNodes(doc.baseline!.document, doc.baseline!.canvas, 0)
      .filter(node => node.layout === 'grid' && node.kind === 'diagram')
      .map(node => ({ documentId: doc.id, name: doc.name, node: this.projection.node(node) })));
    if (input.operation === 'read') {
      if (documents.length !== 1) throw Error('Specify representationId from the pinned document list');
      const selected = nodes.filter(entry => !input.nodeId || entry.node.id === input.nodeId);
      return { version: 0, nodes: selected, edges: documents[0].baseline!.document.edges };
    }
    const query = (input.query ?? '').toLowerCase();
    const hits = nodes.filter(entry => entry.node.layout === 'grid' && JSON.stringify(entry.node.content).toLowerCase().includes(query))
      .map(entry => ({ representationId: entry.documentId, name: entry.name, nodeId: entry.node.id,
        snippet: entry.node.layout === 'grid' ? entry.node.content?.ascii.split('\n').slice(0, 3).join('\n') : '' }));
    return { total: hits.length, hits: hits.slice(input.offset, input.offset + input.limit) };
  }
  tools(step: DiffSessionStep): DiffSessionTool[] {
    const read = [
      this.tool('canvas-api-search', 'Discover short canvas API methods and schemas.', agentToolSchemas['canvas-api-search'], async input => canvasApiSpec(input.query)),
      this.tool('diagram-search', 'Read/search frozen baseline diagrams during analysis. Specify representationId and optionally nodeId to read one diagram. During materialization reads the new proposal; snapshot baseline reads its originals.', agentToolSchemas['diagram-search'], async input => {
        if (step === 'analyze' || !this.changeSessionId) return this.frozenSearch(input);
        const result = await this.agent.call('diagram-search', this.bound(input)) as any;
        if (input.nodeId && Array.isArray(result.nodes)) result.nodes = result.nodes.filter((node: any) => node.id === input.nodeId);
        return result;
      }),
      this.tool('get_repository_diff_hunks', 'Read the immutable hunks captured for this workflow; commits/head cannot change.', agentToolSchemas.get_repository_diff_hunks.safeExtend({ includePatches: z.boolean().default(step === 'analyze') }), async input => {
        const hunks = this.capture.hunks.slice(input.offset, input.offset + input.limit);
        return { ...this.capture.context, total: this.capture.hunks.length,
          nextOffset: input.offset + input.limit < this.capture.hunks.length ? input.offset + input.limit : null,
          hunks: input.includePatches ? hunks : hunks.map(({ patch: _, ...metadata }) => metadata) };
      }),
      this.tool('read_repository_source', 'Read a source file at pinned head (default), a selected commit or a captured hunk parent. Returns numbered source lines; never reads the working tree.', sourceSchema, this.readSource)
    ];
    if (step === 'analyze') return read;
    return [...read,
      this.tool('create_diagram_change_session', 'Create this run\'s one isolated proposal from its frozen baseline and pinned hunks. Safe to repeat with identical arguments.',
        z.object({ diffTree: diffTreeInputSchema.optional(), description: z.string().max(100000).optional() }).strict(), async input => {
          const result = await this.changes.create({ title: this.title, requestId: this.requestId, ...input }, this.capture) as { changeSessionId: string };
          this.changeSessionId = result.changeSessionId;
          await this.onCreated(result.changeSessionId);
          return result;
        }),
      ...(['exec', 'draw_diagram', 'set_diagram_source_mappings', 'update_diagram_change_session', 'read_change_session_diff_tree'] as const).map(name =>
        this.tool(name, name === 'exec' ? 'Execute synchronous short canvas API JavaScript on this proposal. Return results. Attach using canvas.attach; use current document expectedVersion for mutations.'
          : `Call ${name} on this workflow's proposal using the current version and a new requestId for each new mutation.`, name === 'read_change_session_diff_tree' ? agentToolSchemas[name].safeExtend({ includePatches: z.boolean().default(false) }) : agentToolSchemas[name],
        async input => this.agent.call(name as AgentToolName, this.bound(input)))),
      this.tool('complete_diff_session', 'Validate the ready proposal and complete this workflow. Repair errors before retrying.', z.object({}).strict(), async () => {
        if (!this.changeSessionId) throw Error('Create the proposal first');
        const session = await this.changes.get(this.changeSessionId);
        if (session.status !== 'ready' || !session.changes.length) throw Error('Implement changes and mark the proposal ready first');
        const mapped = new Set(session.diffTree?.mappings.flatMap(mapping => mapping.targets.map(target => target.hunkId)));
        const missing = this.capture.hunks.filter(hunk => !mapped.has(hunk.id));
        if (missing.length) throw Error(`DiffTree is missing ${missing.length} hunks: ${missing.map(hunk => hunk.id).join(', ')}`);
        return { changeSessionId: session.id, status: session.status, changes: session.changes.length,
          documents: session.documents.map(doc => ({ id: doc.id, name: doc.name })) };
      })
    ];
  }
  private bound(input: Record<string, unknown>) {
    if (!this.changeSessionId) throw Error('Create this workflow\'s proposal first');
    if (input.changeSessionId && input.changeSessionId !== this.changeSessionId) throw Error('Workflow cannot access another ChangeSession');
    return { ...input, changeSessionId: this.changeSessionId };
  }
}
"},{"path":"domain/mapping/changes/diagramChangeSession.ts","text":"import { diffTreeSummary, diffTreeSummarySchema, validateDiffTree, type ChangeSessionDiffTree, type DiffTreeSummary } from './diffTree';
import { repositoryContextSchema } from '../../core/repositories/repository';
import { CanvasHistory, validateCanvasHistory, type CanvasHistoryRecord } from '../workspace/canvasHistory';
import { z } from 'zod';
import { diagramMigrationSchema, type DiagramMigration } from './diagramMigration';
import type { MappingGridDocument } from '../workspace/mappingGrid';
import type { MappingCanvasState } from '../workspace/mappingWorkspace';
import { deserializeWorkspace } from '../workspace/mappingWorkspaceCodec';
import type { ChangeSessionAcceptance } from '../../core/representations/changeAcceptance';

export const changeId = z.string().min(1).max(200).regex(/^[a-zA-Z0-9_.:-]+$/).refine(id => !['__proto__','constructor','prototype'].includes(id));
export const diagramChangeSchema = z.object({
  id: changeId, title: z.string().trim().min(1).max(200), type: z.union([z.literal(1), z.literal(2), z.literal(3), z.literal(4)]),
  reasons: z.array(z.enum(['1a', '1b'])).default([]), documentId: changeId, nodeId: changeId.optional(),
  dependsOn: z.array(changeId).max(100).default([])
